mapper.select:
        select count(*) from message message
        left join users student on message.send_user_id = student.id
		left join teacher teachers on message.accept_user_id = teachers.id

            and message.id = #{id}
            and message.send_user_id = #{sendUserId}
            and message.accept_user_id = #{acceptUserId}
            and message.create_time = #{createTime}
            and student.nick_name like concat('%',#{stuName},'%')
            and teachers.name like concat('%',#{teaName},'%')
